48	
49	    /** 插入文档并返回自增 ID，初始草稿版本 1、发布版本 0。 */
50	    public long insertDocument(List<String> targetLanguages) {
51	        KeyHolder keyHolder = new GeneratedKeyHolder();
52	        jdbc.update(con -> {
53	            PreparedStatement ps = con.prepareStatement(
54	                    "INSERT INTO document (target_languages, draft_version, published_version) VALUES (?, 1, 0)",
55	                    new String[]{"document_id"});
56	            ps.setString(1, String.join(",", targetLanguages));
57	            return ps;
58	        }, keyHolder);
59	        Number key = keyHolder.getKey();
60	        if (key == null) {
61	            throw new IllegalStateException("文档创建后未返回自增主键");
62	        }
63	        return key.longValue();
64	    }
65	
66	    /** 按 ID 查询文档并加行级写锁（FOR UPDATE），用于串行化同一文档的写操作。 */
67	    public Optional<DocumentRow> findDocumentForUpdate(long documentId) {
68	        List<DocumentRow> rows = jdbc.query(
69	                "SELECT document_id, target_languages, draft_version, published_version "
70	                        + "FROM document WHERE document_id = ? FOR UPDATE",
71	                DOCUMENT_MAPPER, documentId);
