1	package com.example.starter.translation.service;
2	
3	import com.example.starter.translation.api.ApiException;
4	import com.example.starter.translation.domain.Rows.RequestLogRow;
5	import com.example.starter.translation.repo.TranslationRepository;
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.stereotype.Component;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	import java.util.Optional;
11	import java.util.function.Supplier;
12	
13	/**
14	 * 写操作幂等执行器。
15	 * 同一事务内完成：requestId 查重 → 业务变更 → 成功结果落 request_log，原子提交；
16	 * 失败抛异常回滚，requestId 不占键。同键同参重放原成功结果，同键异参返回 409。
17	 * 并发下同键请求由主键约束兜底：后到的插入冲突回滚后重读记录并重放。
18	 */
19	@Component
20	public class WriteExecutor {
21	
22	    private final TranslationRepository repository;
23	    private final TransactionalWrite transactionalWrite;
24	
25	    public WriteExecutor(TranslationRepository repository, TransactionalWrite transactionalWrite) {
26	        this.repository = repository;
27	        this.transactionalWrite = transactionalWrite;
28	    }
29	
30	    /** 执行幂等写操作：requestId 全局唯一，hash 为规范化请求参数摘要。 */
31	    public WriteResult execute(String requestId, String requestHash, Supplier<WriteResult> action) {
32	        try {
33	            return transactionalWrite.run(requestId, requestHash, action);
34	        } catch (WriteResult.ReplaySignal signal) {
35	            return replay(requestId, requestHash);
36	        }
37	    }
38	
39	    private WriteResult replay(String requestId, String requestHash) {
40	        RequestLogRow log = repository.findRequestLog(requestId)
41	                .orElseThrow(() -> ApiException.conflict("requestId 冲突且未找到已提交记录: " + requestId));
42	        if (!log.requestHash().equals(requestHash)) {
43	            throw ApiException.conflict("requestId 已使用且请求参数不同: " + requestId);
44	        }
45	        return new WriteResult(log.responseStatus(), log.responseBody());
46	    }
47	
48	    /**
49	     * 事务内执行：查重、业务变更与去重记录同一事务提交。
50	     * 独立 Spring Bean 以保证 @Transactional 代理生效。
51	     */
52	    @Component
53	    public static class TransactionalWrite {
54	
55	        private final TranslationRepository repository;
56	
57	        public TransactionalWrite(TranslationRepository repository) {
58	            this.repository = repository;
59	        }
60	
61	        @Transactional
62	        public WriteResult run(String requestId, String requestHash, Supplier<WriteResult> action) {
63	            Optional<RequestLogRow> existing = repository.findRequestLog(requestId);
64	            if (existing.isPresent()) {
65	                RequestLogRow log = existing.get();
66	                if (!log.requestHash().equals(requestHash)) {
67	                    throw ApiException.conflict("requestId 已使用且请求参数不同: " + requestId);
68	                }
69	                return new WriteResult(log.responseStatus(), log.responseBody());
70	            }
71	            WriteResult result = action.get();
72	            try {
73	                repository.insertRequestLog(requestId, requestHash, result.status(), result.body());
74	            } catch (DuplicateKeyException e) {
75	                throw new WriteResult.ReplaySignal(requestId, e);
76	            }
77	            return result;
78	        }
79	    }
80	}
