108	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
109	        submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
110	
111	        ApiResult byAuthor = approve(docId, "s1", "en", "alice", 1, newRequestId());
112	        assertThat(byAuthor.status()).isEqualTo(422);
113	
114	        ApiResult wrongVersion = approve(docId, "s1", "en", "bob", 7, newRequestId());
115	        assertThat(wrongVersion.status()).isEqualTo(422);
116	
117	        ApiResult ok = approve(docId, "s1", "en", "bob", 1, newRequestId());
118	        assertThat(ok.status()).isEqualTo(200);
119	        assertThat(ok.body().get("reviewer").asText()).isEqualTo("bob");
120	    }
121	
122	    @Test
123	    @DisplayName("批准失效：源文修订后旧批准失效，发布 422；重新提交并批准后发布成功")
124	    void approvalInvalidatedBySourceRevision() throws Exception {
125	        long docId = createDocument(newRequestId(), "[\"en\"]",
126	                "[{\"segmentId\":\"s1\",\"sourceText\":\"原文\"}]");
127	        submitTranslation(docId, "s1", "en", "alice", "hello", 1, newRequestId());
128	        approve(docId, "s1", "en", "bob", 1, newRequestId());
129	
130	        // 修订源文：源文版本 2，旧批准失效
131	        putJson("/api/documents/" + docId + "/segments/s1/source",
132	                "{\"requestId\":\"" + newRequestId() + "\",\"sourceText\":\"新原文\"}");
133	        ApiResult stalePublish = publish(docId, 3, 0, newRequestId());
134	        assertThat(stalePublish.status()).isEqualTo(422);
135	
136	        // 基于旧源文版本提交译文 422；基于当前版本提交后旧批准失效，发布仍 422
137	        ApiResult staleSubmit = submitTranslation(docId, "s1", "en", "alice", "hi", 1, newRequestId());
138	        assertThat(staleSubmit.status()).isEqualTo(422);
139	        ApiResult resubmit = submitTranslation(docId, "s1", "en", "alice", "new hello", 2, newRequestId());
140	        assertThat(resubmit.status()).isEqualTo(200);
141	        assertThat(resubmit.body().get("translationVersion").asInt()).isEqualTo(2);
142	        ApiResult stillStale = publish(docId, 4, 0, newRequestId());
